// Level 5: end-to-end script evaluation. Exercises lexer, parser, compiler,
// runtime and every builtin through the public API of both shared libraries.
mod common;

use common::*;

fn check_all(cases: &[&str]) {
    let cs = Session::new(Side::C, 0);
    cs.register_print();
    let rs = Session::new(Side::Rust, 0);
    rs.register_print();
    let mut failures = Vec::new();
    for src in cases {
        let a = run_script(&cs, src);
        let b = run_script(&rs, src);
        if a != b {
            failures.push(format!(
                "--- script ---\n{}\n--- C ---\n{:?}\n--- Rust ---\n{:?}",
                src, a, b
            ));
        }
    }
    if !failures.is_empty() {
        panic!(
            "{} of {} scripts mismatched:\n{}",
            failures.len(),
            cases.len(),
            failures.join("\n\n")
        );
    }
}

fn check_all_strict(cases: &[&str]) {
    let cs = Session::new(Side::C, 1);
    cs.register_print();
    let rs = Session::new(Side::Rust, 1);
    rs.register_print();
    let mut failures = Vec::new();
    for src in cases {
        let a = run_script(&cs, src);
        let b = run_script(&rs, src);
        if a != b {
            failures.push(format!(
                "--- script (strict) ---\n{}\n--- C ---\n{:?}\n--- Rust ---\n{:?}",
                src, a, b
            ));
        }
    }
    if !failures.is_empty() {
        panic!(
            "{} of {} strict scripts mismatched:\n{}",
            failures.len(),
            cases.len(),
            failures.join("\n\n")
        );
    }
}

#[test]
fn smoke() {
    check_all(&["1+1", "'a'+'b'", "print(1,2,3)", "throw new Error('x')", "("]);
}

