#[test]
fn statements_and_control_flow() {
    check_all(&[
        "var x = 1; x",
        "var x; x",
        "var x = 1, y = 2; x+y",
        "{ var a = 5; } a",
        "if (1) 2; else 3;",
        "if (0) 2; else 3;",
        "var s=''; for (var i=0;i<5;i++) s+=i; s",
        "var s=''; var i=0; while(i<5){s+=i;i++} s",
        "var s=''; var i=0; do{s+=i;i++}while(i<5); s",
        "var s=''; for (var k in {a:1,b:2}) s+=k; s",
        "var s=''; for (var k in [10,20,30]) s+=k+','; s",
        "var s=''; for (var i=0;i<10;i++){ if(i%2) continue; s+=i; } s",
        "var s=''; for (var i=0;i<10;i++){ if(i>4) break; s+=i; } s",
        "var s=''; outer: for(var i=0;i<3;i++){ for(var j=0;j<3;j++){ if(j>i) continue outer; s+=''+i+j; } } s",
        "var s=''; outer: for(var i=0;i<3;i++){ for(var j=0;j<3;j++){ if(i==1) break outer; s+=''+i+j; } } s",
        "switch(1){case 1: 'one'; break; case 2: 'two'; break; default: 'other'}",
        "var r=''; switch(2){case 1: r+='a'; case 2: r+='b'; case 3: r+='c'; break; default: r+='d'} r",
        "switch('x'){default: 'def'}",
        "try { throw 1 } catch(e) { e }",
        "try { throw new Error('m') } catch(e) { e.message }",
        "try { null.x } catch(e) { e.name }",
        "try { undefinedfn() } catch(e) { e.name }",
        "try { 1 } finally { 2 }",
        "var s=''; try { s+='a'; throw 1 } catch(e){ s+='b' } finally { s+='c' } s",
        "var s=''; try { try { throw 1 } finally { s+='f' } } catch(e) { s+='c' } s",
        "with({a:5}) a",
        "var o={a:1}; with(o){ a=2 } o.a",
        "var s=''; with({x:1}){ s+=x } s",
        ";;;",
        "if(1);",
        "for(;;){break}",
        "var s=''; for(var i in 'abc') s+=i; s",
        "debugger",
        "throw 'plain'",
        "throw 42",
        "(function(){ return })()",
        "(function(){ return 5 })()",
        "(function(){ })()",
    ]);
}

