#[test]
fn objects_and_properties() {
    check_all(&[
        "var o={}; o.a=1; o.a",
        "var o={a:1,b:2}; o.a+o.b",
        "var o={'a':1,\"b\":2,3:4}; o[3]",
        "var o={a:1}; 'a' in o",
        "var o={a:1}; 'b' in o",
        "var o={a:1}; delete o.a; 'a' in o",
        "var o={a:1}; delete o.b",
        "var o={a:1,b:2}; var s=''; for(var k in o) s+=k; s",
        "var o={get x(){return 5}}; o.x",
        "var o={set x(v){this._v=v}}; o.x=3; o._v",
        "var o={get x(){return 1}, set x(v){}}; o.x",
        "var o=Object.create(null); typeof o",
        "Object.keys({a:1,b:2}).join(',')",
        "Object.getOwnPropertyNames({a:1,b:2}).join(',')",
        "Object.getPrototypeOf({})===Object.prototype",
        "Object.getPrototypeOf(Object.create(null))",
        "var o={}; Object.defineProperty(o,'x',{value:1}); o.x",
        "var o={}; Object.defineProperty(o,'x',{value:1}); o.x=2; o.x",
        "var o={}; Object.defineProperty(o,'x',{value:1,writable:true}); o.x=2; o.x",
        "var o={}; Object.defineProperty(o,'x',{value:1}); Object.keys(o).length",
        "var o={}; Object.defineProperty(o,'x',{value:1,enumerable:true}); Object.keys(o).length",
        "var o={}; Object.defineProperties(o,{a:{value:1},b:{value:2}}); o.a+o.b",
        "JSON.stringify(Object.getOwnPropertyDescriptor({a:1},'a'))",
        "Object.getOwnPropertyDescriptor({a:1},'b')",
        "var o=Object.freeze({a:1}); o.a=2; o.a",
        "Object.isFrozen(Object.freeze({}))",
        "Object.isFrozen({})",
        "var o=Object.seal({a:1}); o.b=2; 'b' in o",
        "Object.isSealed(Object.seal({}))",
        "Object.preventExtensions({}); 1",
        "Object.isExtensible({})",
        "Object.isExtensible(Object.preventExtensions({}))",
        "({}).toString()",
        "({}).valueOf()===undefined",
        "({}).hasOwnProperty('a')",
        "({a:1}).hasOwnProperty('a')",
        "({}).hasOwnProperty('toString')",
        "({}).propertyIsEnumerable('toString')",
        "({a:1}).propertyIsEnumerable('a')",
        "Object.prototype.isPrototypeOf.call(Object.prototype,{})",
        "String(Object)",
        "Object(1) instanceof Number",
        "Object('a') instanceof String",
        "Object(true) instanceof Boolean",
        "typeof Object()",
        "Object.keys('abc').join(',')",
        "var o={}; o[1]=1; o['1']",
        "var o={toString:function(){return 'k'}}; var p={}; p[o]=1; p.k",
        "var o={valueOf:function(){return 3}}; o*2",
        "var o={toString:function(){return '3'}}; o*2",
        "var o={valueOf:function(){return {}},toString:function(){return '4'}}; o*2",
        "var o={valueOf:function(){return {}},toString:function(){return {}}}; try{o*2}catch(e){e.name}",
        "var o = {a:{b:{c:42}}}; o.a.b.c",
        "var o = {}; o.a = o; typeof o.a.a.a",
        "({1e21:'x'})[1e21]",
        "var o={}; o.__proto__ = {q:7}; o.q",
        "var a={}; a.constructor===Object",
    ]);
}

